    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal static int CFL_IDX_U(int idx) => idx >> CFL_ALPHABET_SIZE_LOG2;

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal static int CFL_IDX_V(int idx) => idx & (CFL_ALPHABET_SIZE - 1);

    // CFL_SIGN_U is equivalent to (js + 1) / 3 for js in 0 to 8
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal static int CFL_SIGN_U(int js) => ((js + 1) * 11) >> 5;

    // CFL_SIGN_V is equivalent to (js + 1) % 3 for js in 0 to 8
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal static int CFL_SIGN_V(int js) => (js + 1) - CFL_SIGNS * CFL_SIGN_U(js);

    // The context for the alpha_u symbol is the sign of the u component, plus a
    // ternary digit taken from the sign of v.
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal static int CFL_CONTEXT_U(int js) => js + 1 - CFL_SIGNS;

    // Also, the contexts are symmetric under swapping the planes.
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal static int CFL_CONTEXT_V(int js) => CFL_SIGN_V(js) * CFL_SIGNS + CFL_SIGN_U(js) - CFL_SIGNS;

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal static int FWD_RF_OFFSET(int @ref) => @ref - LAST_FRAME;

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal static int BWD_RF_OFFSET(int @ref) => @ref - BWDREF_FRAME;
